import{_ as t,o as e,c as _,a3 as o}from"./chunks/framework.DdpBa4_E.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/17-依恋需要：绝非只是针对孩子.md","filePath":"books/attached/17-依恋需要：绝非只是针对孩子.md","lastUpdated":1794316978000}'),p={name:"books/attached/17-依恋需要：绝非只是针对孩子.md"};function r(i,a,s,l,n,c){return e(),_("div",null,[...a[0]||(a[0]=[o('<h3 id="依恋需要-绝非只是针对孩子" tabindex="-1">依恋需要：绝非只是针对孩子 <a class="header-anchor" href="#依恋需要-绝非只是针对孩子" aria-label="Permalink to &quot;依恋需要：绝非只是针对孩子&quot;">​</a></h3><p>鲍尔比一再强调，依恋是贯穿人们整个生命的不可或缺部分。而玛丽·梅因（Mary Main）后来也发现，人们在生命早期对于养育者的依恋方式，也会按照不同类型延续到成人阶段，甚至还会影响到他们自己今后的教养方式。辛迪·哈赞和菲利普·谢弗以玛丽·梅因的研究作为基础，发现在恋爱关系中，成年人也会具有不同的依恋风格。他们最初的发现，来自于刊登在《落基山新闻报》（Rocky Mountain News）上的“恋爱测验”（lovequiz），这则测验要求被调查者们从三个条目中选出一个最符合的，以此来描述他们在恋爱关系中的感受与态度。以下就是那三个条目，它们分别对应三种依恋风格：</p><ul><li><p>我觉得和别人亲近是件很容易的事情，我非常享受那种与别人互相依靠的感觉。我也基本不会担心自己被抛弃，或者别人离我太近这类事情。（用以测量安全型依恋风格）</p></li><li><p>我有时候会对靠别人太近感到不适。我发现自己很难做到完全信任别人，也不放心自己完全依靠他人。别人靠我太近，我就会开始焦虑，但是通常来说，我的恋人又会提出一些令我不适的亲密请求。（用以测量回避型依恋风格）</p></li><li><p>我总觉得我想靠近他人，却对此有所迟疑。我经常会担心自己的伴侣不是真的爱我，或是想跟我分开。我就是渴望与他人融为一体，这种渴望常常把别人吓到。（用以测量焦虑型依恋风格）</p></li></ul><p>值得注意的是，调查结果显示依恋风格在成年人中的分布，与其在幼儿中非常相似，大多数被调查者属于安全型，剩下的基本上在焦虑型和回避型之间对半分。研究者们还发现，每种依恋风格下的人，对于自身、伴侣、恋爱关系以及性爱方面的态度，又都是千差万别的。</p><p>哈赞和谢弗以及其他学者的后续研究也证实了以上的调查结果。正如鲍尔比所言，依恋在我们的毕生发展中，都扮演者持续而重要的角色。不同点仅仅在于，成人有着更高级的概括能力，因此我们即使非常需要他人的长久陪伴，也可以暂时安抚自己，告诉自己对方的心灵是与我们相通的。而相同之处则很明显，那就是对于亲密关系的诉求，以及对于伴侣回应性的一再确认，都会不可避免地贯穿于我们的一生。</p><p>不幸的是，正如从前亲子关系受到忽视那样，如今成人依恋的影响力同样不受重视。在成年人中，对恋爱关系中依赖性的诟病，依然占据着主流观点。</p>',6)])])}const h=t(p,[["render",r]]);export{u as __pageData,h as default};
